export const chapter3Id = (number: StoryLessonNumber) => `conversational-skills-L3-C3-${number}-${chapter3Episodes[number].skill}-ja-v1`;
export function buildEverydayLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildNewBeginningLesson(number, previous, 'https://api.fluentxverse.com', reference, {
    episode: chapter3Episodes[number], id: chapter3Id(number), chapterName: 'Everyday Life & Unexpected Moments',
    setting: 'Kamo House and its cafe in Kyoto, Leo\'s bakery, Emma\'s design work, and Nao\'s gallery exhibition. All story characters are adults.',
    previousSummary: index === 0 ? 'Chapter 2 ended with Emma accepting Leo\'s invitation to spend time together after their Kyoto outings.' : chapter3Episodes[requireDefined(storyLessonNumbers[index - 1], "storyLessonNumbers[index - 1]")].closing,
    storyNotes: 'User-supplied eight-episode Chapter 3 plan, mapped to Lessons 1-4 and 6-9; 5 and 10 remain personalized checkpoints. Warm slice-of-life drama: work schedules, cafe staffing, shared dinner, a mistaken assumption, Nao\'s career opportunity, clarification and celebration. Aya is Leo\'s bakery coworker, not his girlfriend. Emma acknowledges her own assumption; Leo explains without accepting blame for having lunch with a coworker. Nao receives an invitation during the same workweek; preparation Thursday, label check Friday, exhibition Saturday ending5, packing until6 and celebration6:30. Use direct role assignments and natural tutor-first dialogue. No new images or Chapter 1/2 scene assets.',
  });
  lesson.storyData.characters = [
    { id: 'emma', name: 'Emma', role: 'main', description: 'A graphic designer at Kamo House balancing urgent work, friendships, and her growing relationship with Leo.' },
    { id: 'claire', name: 'Claire', role: 'supporting', description: 'Helps run the cafe, manages a staffing problem, and brings everyone together for dinner and a celebration.' },
    { id: 'leo', name: 'Leo', role: 'supporting', description: 'A bakery worker from Bristol, busy with extra orders, who wants to communicate more clearly with Emma.' },
    { id: 'nao', name: 'Nao', role: 'supporting', description: 'A ceramics student from Fukuoka invited to show her work at a gallery; learns to explain her work with confidence.' },
    { id: 'aya', name: 'Aya', role: 'supporting', description: 'Leo\'s bakery coworker. Their work lunch is mistaken for a date by Emma.' },
  ];
  return { course: 'conversational-skills', level: 3, chapter: 3, lessonNumber: number, levelBadge: 'BEGINNER', chapterLabel: 'Chapter 3: Everyday Life & Unexpected Moments', status: previous?.status || 'draft', overlayColor: '#17252bcc', supportLanguage: 'ja', ...lesson };
}
export function buildEverydayChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildEverydayLesson(number, {}, reference));
}
